from pathlib import Path
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.units import mm
from pypdf import PdfReader
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'Report/Forecast_Evidence_and_Decision_Framework.pdf'
styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='TitleX',parent=styles['Title'],fontName='Helvetica-Bold',fontSize=22,leading=26,textColor=colors.HexColor('#17384C'),spaceAfter=8));styles.add(ParagraphStyle(name='Sub',parent=styles['Normal'],fontSize=9,textColor=colors.HexColor('#557080'),spaceAfter=12));styles.add(ParagraphStyle(name='BodyX',parent=styles['BodyText'],fontSize=10,leading=14,spaceAfter=8));styles.add(ParagraphStyle(name='HeadX',parent=styles['Heading2'],fontSize=14,leading=18,textColor=colors.HexColor('#087E8B'),spaceBefore=8,spaceAfter=5));styles.add(ParagraphStyle(name='CodeX',parent=styles['Code'],fontName='Courier',fontSize=8.5,leading=12,leftIndent=10,spaceAfter=9))
story=[]
def add(t,s='BodyX'):story.append(Paragraph(t,styles[s]))
def footer(c,d):c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#557080'));c.drawString(18*mm,12*mm,'Forecast evidence and decision framework');c.drawRightString(192*mm,12*mm,str(d.page))
add('Forecast Evidence and Decision Framework','TitleX');add('A short guide to evaluating candidate forecasts and presenting them at each decision time','Sub')
add('Purpose','HeadX');add('Separate three steps: research evidence shows what a model has demonstrated; a forecast object presents its current estimates; a decision layer decides what action to take. This report describes a proposed framework. It does not report newly measured model results.')
add('1. Research evidence','HeadX');add('For each direction or magnitude candidate, compare it with both a simple baseline and the current best model. Report the features used, measured improvement, performance across time periods, and conditions where performance changes. For direction, show log loss and Brier score. For magnitude, show mean absolute error (MAE). Include probability metrics only for a direction model that outputs probabilities.')
add('2. Forecast object at each timestamp','HeadX');add('Use one consistent record for every forecast. Include the target and horizon, direction probabilities (if available), predicted median absolute move, probability of an extreme move (if calibrated and evaluated), relevant market context, and the status of the supporting model. The exact forecast values update with each timestamp.')
add('Example format (illustrative only)','HeadX');add('BTC - 48H FORECAST<br/><br/>Direction<br/>P(UP): [model output]<br/>P(DOWN): [model output]<br/><br/>Magnitude<br/>Predicted median absolute move: [model output] log bps<br/><br/>Tail / extreme<br/>P(|return| &gt; 500 bps): [model output]<br/><br/>Market context: [relevant feature or regime state]<br/><br/>Model evidence<br/>Direction model: [status]<br/>Magnitude model: [status]','CodeX');add('The example values in the source images (such as 62%, 340 log bps and 24%) are placeholders. They are not verified experiment results and should not be presented as measured forecasts.','Sub')
story.append(PageBreak());add('3. Keep forecasting separate from trading decisions','TitleX');add('A forecast describes model estimates. A separate decision process may use those estimates together with costs, risk limits and other requirements to choose long, short or no trade, position size and execution. A forecast alone is not a buy or sell instruction.')
add('4. Common candidate report','HeadX');data=[['Item','What to report'],['Target','Direction, magnitude or tail event; horizon and units'],['Baseline','Baseline prediction and its score'],['Current best','Strongest existing model and its score'],['Candidate','Model and feature inputs'],['Improvement','Change versus baseline and current best'],['Stability','Scores across time periods'],['Context','Conditions associated with stronger or weaker results'],['Live output','Forecast fields produced at a decision timestamp'],['Status','Exploratory, development candidate, frozen for fresh confirmation, or confirmed']];t=Table([[Paragraph(str(v),styles['BodyX']) for v in row] for row in data],colWidths=[38*mm,142*mm],repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#17384C')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.HexColor('#EDF4F6'),colors.white]),('GRID',(0,0),(-1,-1),.3,colors.HexColor('#D7E2E6')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),3)]));story.extend([t,Spacer(1,7)])
add('Reporting rule','HeadX');add('State measured evidence and its evaluation period clearly. Mark illustrative values as examples. Do not describe a candidate as confirmed unless its status is supported by the evaluation process.')
SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=16*mm,bottomMargin=20*mm,title='Forecast Evidence and Decision Framework',author='ScaleWave').build(story,onFirstPage=footer,onLaterPages=footer)
r=PdfReader(OUT);assert len(r.pages)==2;txt='\
'.join(p.extract_text() for p in r.pages);assert 'illustrative only' in txt.lower() and 'not a buy or sell instruction' in txt.lower();print(OUT)
